+  const loaded = loadTypeScriptModule(configFile) as { default?: SsgConfig } | SsgConfig;
+  const config = ('default' in loaded ? loaded.default : loaded) as SsgConfig | undefined;
+  if (!config || (config.plugins !== undefined && !Array.isArray(config.plugins))) {
+    throw new Error(`Invalid SSG config: ${configFile}`);
+  }
+  return [...(config.plugins ?? []), ...(options.plugins ?? [])];
+}

