  const plugin = new DevServerPlugin(options.port ?? 3000);
  const engine = await createEngine(options, [plugin]);
  try {
    await engine.start();
    await engine.build();
  } catch (error) {
    await engine.end();
    throw error;
  }
  return { port: plugin.port, close: () => engine.end() };
}

